admin
      .from("channel_sessions")
      // `last_qr_at` não existe em channel_sessions; o equivalente real é
      // `last_status_change_at` (quando a sessão mudou de estado pela última
      // vez — inclusive ao entrar em SCAN_QR_CODE).
      .select("id, waha_session_name, status, last_status_change_at, updated_at")
      .eq("organization_id", id)

admin.from("calendar_connections").upsert(
    {
      organization_id: organizationId,
      user_id: userId,
      // A CONSTANTE também aqui, embora o literal estivesse CERTO: enquanto o
      // único lugar que escreve o valor certo o escreve à mão, o símbolo
      // canônico segue órfão — e foi a orfandade que deixou três leituras
      // divergirem sem nada acusar.
      provider: PROVEDOR_GOOGLE,
      account_email: conta.conta.email,
      oauth_access_token_encrypted: accessCifrado,
      // Quando o Google não reenviou a chave e já havia uma guardada, a coluna
      // fica FORA do upsert: `on conflict do update` só toca o que recebe, então
      // omitir preserva. Mandar `null` aqui apagaria a chave que faz a conexão
      // sobreviver à primeira hora — é a mesma armadilha de `fundirTokens`, um
      // andar acima.
      ...(refreshCifrado ? { oauth_refresh_token_encrypted: refreshCifrado } : {}),
      token_expires_at: token.expira_em,
      scopes: token.scope,
      status: "healthy",
      last_sync_error: null,
    },
    { onConflict: "organization_id,user_id,provider,account_email" },
  )
    .select("id")
    .single()

admin.from("calendar_connection_calendars").upsert(
      {
        organization_id: organizationId,
        connection_id: conexaoGravada.id,
        external_calendar_id: conta.conta.email,
        name: conta.conta.email,
        is_primary: true,
        // O fuso que até aqui só ia para o audit. `null` quando o Google não mandou: quem
        // lê trata ausência como "não sei" e cai no fuso da organização — nunca em UTC,
        // que é ausência disfarçada de escolha.
        time_zone: conta.conta.fuso,
      },
      { onConflict: "organization_id,connection_id,external_calendar_id" },
    )

admin
      .from("channel_sessions")
      .select("id, waha_session_name, display_name, phone_number, status, daily_message_limit")
      .eq("organization_id", org.orgId)
      // Canal arquivado foi excluído pelo usuário: não volta como opção aqui.
      .is("archived_at", null)
      // Ritmo de envio é regra de canal de MENSAGEM. A linha de chamada de voz
      // (spec 18) não dispara nada e não tem intervalo a calibrar.
      .in("provider", [...PROVIDERS_DE_MENSAGEM])
      .order("created_at", { ascending: true })

admin
    .from("channel_sessions")
    .select("id")
    .eq("id", channel_session_id)
    .eq("organization_id", org.orgId)
    // O MESMO filtro do GET, e não por simetria: sem ele a tela sumia com a
    // conexão excluída e a rota continuava aceitando gravar knobs e teto diário
    // nela — configuração viva pendurada num canal que não envia mais, à espera
    // de confundir quem investigar o próximo envio que não saiu.
    .is("archived_at", null)
    .maybeSingle()

admin
    .from("channel_sessions")
    // As COLUNAS do ref vêm do seam. Escrevê-las à mão aqui nomeia os providers
    // — e o `lint:channels` reprovou a primeira versão deste arquivo por isso,
    // que é a catraca funcionando.
    .select(`id, ${CHANNEL_SESSION_REF_COLUMNS}`)
    .eq("organization_id", org.orgId)
    .eq("id", sessao.id)
    .maybeSingle()

db
        .from("calendar_connections")
        .update({
          updated_at: new Date().toISOString(),
          ...(complete && completedCalendars > 0
            ? { last_sync_error: null, last_sync_at: new Date().toISOString() }
            : {}),
        })
        .eq("organization_id", org)
        .eq("id", connection.id)

admin
        .from("channel_sessions")
        .select("waha_session_name, provider")
        .eq("organization_id", c.organization_id)
        .eq("status", "WORKING")
        // Sem o filtro, a linha de chamada de voz (spec 18) — que nasce
        // `WORKING` ao parear — podia ganhar este `limit(1)` sem ordenação e
        // devolver `waha_session_name` nulo: a foto de todo mundo parava de
