        .in("provider", [...PROVIDERS_DE_MENSAGEM])
        .limit(1)
        .maybeSingle()

supabase
    .from("crm_stages")
    // A autoria entra na MESMA leitura que a tela de etapas já faz. Uma segunda
    // consulta só para ela seria um round-trip por render numa tela de
    // configuração — e um caminho a mais para a lista e a autoria divergirem.
    .select("id, name, is_won, is_lost, agent_stage_hint, last_change_actor_kind, last_change_at")
    .eq("organization_id", orgId)
    .eq("pipeline_id", pipelineId)
    .eq("is_archived", false)
    .order("position", { ascending: true })

createAdminClient()
        .from("user_organizations")
        .select(
          // Dois embeds do MESMO `organizations`, como manda o PostgREST quando a
          // mesma relação aparece duas vezes: `organizations(...)` continua sendo
          // o que a membership sempre trouxe (nome, IDIOMA e FUSO da empresa — o
          // idioma decide a tela inteira e não pode depender de um embed que a
          // issue #1341 acabou de engordar), e o alias traz só as portas da EMPRESA.
          // `timezone` veio do main (fuso da organização nas listas, #1290) e convive
          // com o alias: um embed por relação, sem renomear o que já existia.
          "organization_id, role, interface_settings, accepted_at, organizations(display_name, locale, timezone), interface_da_empresa:organizations(interface_settings)",
        )
        .eq("user_id", user.id)
        .is("revoked_at", null)
        .order("accepted_at", { ascending: true, nullsFirst: true })
        .order("organization_id", { ascending: true })

admin
    .from("channel_sessions")
    .select("id, display_name, phone_number, status")
    .eq("organization_id", organizationId)
    .is("archived_at", null)
    // A faixa diz "nenhuma mensagem entra nem sai por esta conexão" e leva a
    // Conexões. A linha de chamada de voz (spec 18) não é vigiada pelo cron de
    // saúde (nenhum adapter a consulta), então o `status` dela envelhece parado:
    // anunciá-la aqui seria a faixa permanente que ensina a ignorar a faixa.
    .in("provider", [...PROVIDERS_DE_MENSAGEM])
    .in("status", [...STATUS_QUE_AVISAM])

admin
    .from("messages")
    .insert({
      organization_id: orgId,
      conversation_id: conversationId as string,
      // NOT NULL na tabela. Esquecê-lo fez o insert falhar e — porque a rota
      // descartava o resultado — a falha virou "recebido: 1" com nada gravado.
      channel_session_id: sessao.id,
      contact_id: contactId as string,
      direction: "inbound",
      status: "delivered",
      // A Meta manda `contacts` (plural); o CHECK do banco espera `contact`.
      type: e.type === "text" ? "text" : e.type,
      body: e.type === "contact" ? (e.sharedContact?.name ?? e.text) : e.text,
      external_id: e.externalId,
      // O webhook oficial entrega o media_id, não um arquivo que o browser
      // consiga abrir. Mantemos um ponteiro opaco para o adapter resolver pela
      // Graph API; sem ele a bolha nem é renderizada e o worker pula a mídia.
      media_url: e.media ? `meta-media:${e.media.id}` : null,
      media_mime: e.media?.mime ?? null,
      sent_at: e.sentAt.toISOString(),
      metadata: {
        ...(e.media ? { meta_media_id: e.media.id, voice: e.media.voice } : {}),
        ...(e.sharedContact ? { shared_contact: e.sharedContact } : {}),
      },
    })
    .select("id")
    .maybeSingle()

admin
      .from("channel_sessions")
      // `meta_phone_number_id` entra na seleção porque é a segunda metade da chave da
      // credencial (`organization_id` + ele): sem o número, quem chama não tem como
      // pedir a credencial DESTA sessão e volta a olhar o ambiente — que é o defeito
      // que a fatia F4 da #850 fecha.
      .select("id, organization_id, meta_waba_id, meta_phone_number_id")
      .eq("organization_id", organizationId)
      .eq("provider", CHANNEL_PROVIDER_META)
      .order("created_at", { ascending: true })
      .limit(1)

admin
      .from("messages")
      .update({
        status: msg.status,
        ...(msg.errorReason ? { error_message: msg.errorReason, error_code: "zernio_error" } : {}),
      })
      .eq("organization_id", input.organizationId)
      .eq("channel_session_id", input.channelSessionId)
      .eq("external_id", msg.externalId)
      // Não rebaixa: `read` chegando depois de `delivered` é progresso, mas um
      // `delivered` atrasado depois de `read` voltaria o tique para trás. A
      // ordem de entrega do webhook não é garantida.
      .not("status", "in", "(read)")
      .select("id")

admin
    .from("messages")
    .insert({
      organization_id: input.organizationId,
      conversation_id: input.conversationId,
      contact_id: input.contactId,
      channel_session_id: input.channelSessionId,
      external_id: msg.externalId,
      // ─── Por que a SAÍDA também entra ──────────────────────────────────
      //
      // A primeira versão descartava tudo que era `outgoing`, para não duplicar
      // os envios do próprio CRM. O efeito colateral custou caro: mensagem
      // mandada do celular do operador, ou por outra plataforma ligada à mesma
      // conta, NUNCA aparecia — e o histórico do cliente ficava pela metade sem
      // nada avisando.
      //
      // A duplicação que se temia já estava resolvida por outro lado: o
      // `unique (organization_id, external_id)` devolve 23505 no eco do nosso
      // próprio envio, e o chamador lê isso como "duplicate", não como erro.
      direction: msg.direction,
      // ─── Toda linha nascida do webhook veio de FORA do CRM ──────────────
      //
      // O default da coluna é `'crm'`, e ele mente aqui: quem passou por este
      // arquivo chegou pelo webhook do provider, não pelo composer. O canal por
      // QR já carimba `external_device` no mesmo lugar.
      //
      // Não é cosmético. As três funções de fricção contam SÓ
      // `external_device`, então sem este campo o painel lia "zero atendimento
      // por fora" neste número — mesmo com o operador respondendo o dia inteiro
      // pelo celular. E `removerEcoDoProprioEnvio` filtra por este valor: sem
      // ele, o eco do nosso próprio envio escapa da rede e vira linha
      // duplicada na tela.
      sent_via: "external_device",
      status: msg.direction === "outbound" ? (msg.status ?? "sent") : "delivered",
      type: temAnexo ? tipoDoAnexo(primeiro?.type) : "text",
      body: msg.text,
      // A URL do anexo NÃO é pública: é endpoint autenticado do provider, e a
      // plataforma descarta a mídia depois de um tempo. Ela é PONTEIRO, não
      // conteúdo — e é por isso que grava aqui e o worker baixa os bytes já.
      //
      // Antes esta linha guardava os anexos só no `metadata`, e `media_url`
      // ficava nulo: o worker de persistência saía com "no media_url" e a
      // mídia do cliente virava linha sem bytes. O atendente via "imagem" sem
      // imagem — e como ele responde à mão, era o pior defeito do canal.
      ...(temAnexo && primeiro?.url
        ? { media_url: primeiro.url, media_mime: mimeDoAnexo(primeiro.type) }
        : {}),
      metadata: temAnexo ? { provider_attachments: msg.attachments } : {},
      ...(msg.sentAt ? { sent_at: msg.sentAt } : {}),
    })
    .select("id")
    .maybeSingle()

admin
    .from("crm_stages")
    // `is_lost` entra porque a decisão de perda (#917) é sobre esta coluna: sem
    // ela, etapa de perda é indistinguível de etapa comum e o agente escreveria a
    // etapa que o banco recusa — recusa que chega ao worker como falha de escrita.
    .select("id, name, agent_stage_hint, is_archived, is_lost")
    .eq("organization_id", input.organizationId)
    .eq("pipeline_id", lead.pipeline_id)

supabase
    .from("channel_sessions")
    .update({
      archived_at: agora,
      status: "STOPPED",
      last_status_change_at: agora,
      // A identidade do lado do WaCalls deixou de existir; guardá-la faria um
      // pareamento futuro tentar reusar um id que o processo não conhece mais.
      wacalls_session_id: null,
      wacalls_paired_at: null,
    })
    .eq("organization_id", organizationId)
    .eq("id", linha.id)

admin
    .from("messages")
    .select("id, body, type")
    .eq("organization_id", organizationId)
    .eq("conversation_id", conversationId)
    .eq("direction", "outbound")
    // `sent_via` separa o que NASCEU aqui do que veio do celular: a linha do
    // celular é gravada como `external_device` e nunca pode servir de álibi.
    //
    // `automation` entrou junto do carimbo novo (#652). A mensagem que a REGRA
    // manda nasceu aqui tanto quanto a da IA e a do composer; sem ela nesta
    // lista, o eco do próprio envio da regra era lido como resposta pelo celular
    // e a IA ficava pausada na conversa por causa de uma mensagem que o CRM
    // mandou sozinho. Lista e carimbo andam juntos: quem escreve estes valores é
    // `origemDaMensagem`, em `app/api/v1/messages/_handler.ts`.
    //
    // `system` ENTRA pela mesma razão, e o sintoma seria idêntico: é o valor que
    // o envio por TOKEN DE SERVIDOR grava (#866). Fora desta lista, a linha da
    // integração deixa de ser reconhecida como envio NOSSO, o eco do próprio
    // envio vira "resposta pelo celular" e cala a IA por três horas.
    .in("sent_via", ["ai", "user", "automation", "system"])
    // Sem `external_id` = ainda não confirmada pelo canal = ainda em voo. É esta
    // a janela exata em que o eco é indistinguível de digitação humana.
    .is("external_id", null)
    .in("status", ["queued", "sending"])
    .gte("created_at", desde)
    .limit(20)

admin
    .from("messages")
    // `channel_session_id` entra no select porque é ele que resolve QUEM baixa.
    // Sem a coluna, o worker não tem como pedir o adapter e voltaria a
    // depender de uma função fixa de um canal só.
    .select(
      "id, organization_id, conversation_id, channel_session_id, media_url, media_mime, media_storage_path, metadata",
    )
    .eq("id", messageId)
    .eq("organization_id", row.organization_id)
    .maybeSingle()
